window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-5ba226bbda222c4a"]={"versions": [{"id": "FIG-5ba226bbda222c4a", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Protokoll- und Paketformat-Diagramm (Bit-/Byte-Layout eines Netzwerkprotokolls). Das Diagramm spezifiziert das exakte 16-Byte (128-Bit) umfassende Speicher- und Serialisierungsformat von „Type 1 Entries“ (Diensteinträge bzw. Entries for Services) innerhalb des SOME/IP Service Discovery Protokolls (SOME/IP-SD) auf Protokoll- bzw. Netzwerkebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Format ist als 32-Bit breites Raster strukturiert und gliedert sich in folgende Felder:</p>\n<ul class=\"fig-list\"><li><code>Type</code>: 8 Bit (Bit offset 0–7), Kennzeichnung des Eintragstyps.\n</li><li><code>Index 1st options</code>: 8 Bit (Bit offset 8–15), Index auf die erste Optionsmenge im Options-Array.\n</li><li><code>Index 2nd options</code>: 8 Bit (Bit offset 16–23), Index auf die zweite Optionsmenge im Options-Array.\n</li><li><code># of opt 1</code>: 4 Bit (Bit offset 24–27), Anzahl der Optionen der ersten Gruppe.\n</li><li><code># of opt 2</code>: 4 Bit (Bit offset 28–31), Anzahl der Optionen der zweiten Gruppe.\n</li><li><code>Service ID</code>: 16 Bit (Bit offset 0–15 des zweiten 32-Bit-Worts), eindeutige Dienstkennung.\n</li><li><code>Instance ID</code>: 16 Bit (Bit offset 16–31 des zweiten 32-Bit-Worts), Kennung der Dienstinstanz.\n</li><li><code>Major Version</code>: 8 Bit (Bit offset 0–7 des dritten 32-Bit-Worts), Hauptversionsnummer des angebotenen oder angeforderten Dienstes.\n</li><li><code>TTL</code> (Time to Live): 24 Bit (Bit offset 8–31 des dritten 32-Bit-Worts), Gültigkeitsdauer des Eintrags in Sekunden.\n</li><li><code>Minor Version</code>: 32 Bit (Bit offset 0–31 des vierten 32-Bit-Worts), Unterversionsnummer des Dienstes.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Datenformat ohne dynamischen Sequenzablauf. Bei der Serialisierung bzw. Deserialisierung eines SOME/IP-SD-Pakets werden die Felder in Big-Endian-Reihenfolge übertragen bzw. interpretiert. Der Sender füllt Dienstidentifikatoren, Versionsstände sowie Lebensdauer und referenziert über die Indizes und Zähler die zugehörigen Einträge im nachfolgenden Options-Array. Der Empfänger wertet diese Felder zur Dienstauflösung, Versionierungsprüfung und Verwaltung der dynamischen Service-Bindings aus.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Layout ist normativ für alle Type-1-Diensteinträge in SOME/IP Service Discovery. Feldgrenzen, Wortbreiten und Bit-Offsets müssen bitgenau eingehalten werden. Besondere Beachtung gilt der asymmetrischen Aufteilung des dritten Datenworts (8 Bit Major Version gefolgt von 24 Bit TTL) sowie der 4-Bit-Quantisierung der Optionszähler (<code># of opt 1</code>, <code># of opt 2</code>), die jeweils maximal 15 Optionen pro Referenzierungsblock zulässt.</p>"}, {"id": "FIG-a2e1cb92ea5e27ca", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Protokoll- und Paketformat-Diagramm (Bit-/Byte-Layout eines Netzwerkprotokolls). Das Diagramm spezifiziert das exakte 16-Byte (128-Bit) umfassende Speicher- und Serialisierungsformat von „Type 1 Entries“ (Diensteinträge bzw. Entries for Services) innerhalb des SOME/IP Service Discovery Protokolls (SOME/IP-SD) auf Protokoll- bzw. Netzwerkebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Format ist als 32-Bit breites Raster strukturiert und gliedert sich in folgende Felder:</p>\n<ul class=\"fig-list\"><li><code>Type</code>: 8 Bit (Bit offset 0–7), Kennzeichnung des Eintragstyps.\n</li><li><code>Index 1st options</code>: 8 Bit (Bit offset 8–15), Index auf die erste Optionsmenge im Options-Array.\n</li><li><code>Index 2nd options</code>: 8 Bit (Bit offset 16–23), Index auf die zweite Optionsmenge im Options-Array.\n</li><li><code># of opt 1</code>: 4 Bit (Bit offset 24–27), Anzahl der Optionen der ersten Gruppe.\n</li><li><code># of opt 2</code>: 4 Bit (Bit offset 28–31), Anzahl der Optionen der zweiten Gruppe.\n</li><li><code>Service ID</code>: 16 Bit (Bit offset 0–15 des zweiten 32-Bit-Worts), eindeutige Dienstkennung.\n</li><li><code>Instance ID</code>: 16 Bit (Bit offset 16–31 des zweiten 32-Bit-Worts), Kennung der Dienstinstanz.\n</li><li><code>Major Version</code>: 8 Bit (Bit offset 0–7 des dritten 32-Bit-Worts), Hauptversionsnummer des angebotenen oder angeforderten Dienstes.\n</li><li><code>TTL</code> (Time to Live): 24 Bit (Bit offset 8–31 des dritten 32-Bit-Worts), Gültigkeitsdauer des Eintrags in Sekunden.\n</li><li><code>Minor Version</code>: 32 Bit (Bit offset 0–31 des vierten 32-Bit-Worts), Unterversionsnummer des Dienstes.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Datenformat ohne dynamischen Sequenzablauf. Bei der Serialisierung bzw. Deserialisierung eines SOME/IP-SD-Pakets werden die Felder in Big-Endian-Reihenfolge übertragen bzw. interpretiert. Der Sender füllt Dienstidentifikatoren, Versionsstände sowie Lebensdauer und referenziert über die Indizes und Zähler die zugehörigen Einträge im nachfolgenden Options-Array. Der Empfänger wertet diese Felder zur Dienstauflösung, Versionierungsprüfung und Verwaltung der dynamischen Service-Bindings aus.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Layout ist normativ für alle Type-1-Diensteinträge in SOME/IP Service Discovery. Feldgrenzen, Wortbreiten und Bit-Offsets müssen bitgenau eingehalten werden. Besondere Beachtung gilt der asymmetrischen Aufteilung des dritten Datenworts (8 Bit Major Version gefolgt von 24 Bit TTL) sowie der 4-Bit-Quantisierung der Optionszähler (<code># of opt 1</code>, <code># of opt 2</code>), die jeweils maximal 15 Optionen pro Referenzierungsblock zulässt.</p>"}, {"id": "FIG-8eb569ef7fc86f0e", "releases": ["R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Protokoll- und Paketformat-Diagramm (Bit-/Byte-Layout eines Netzwerkprotokolls). Das Diagramm spezifiziert das exakte 16-Byte (128-Bit) umfassende Speicher- und Serialisierungsformat von „Type 1 Entries“ (Diensteinträge bzw. Entries for Services) innerhalb des SOME/IP Service Discovery Protokolls (SOME/IP-SD) auf Protokoll- bzw. Netzwerkebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Format ist als 32-Bit breites Raster strukturiert und gliedert sich in folgende Felder:</p>\n<ul class=\"fig-list\"><li><code>Type</code>: 8 Bit (Bit offset 0–7), Kennzeichnung des Eintragstyps.\n</li><li><code>Index 1st options</code>: 8 Bit (Bit offset 8–15), Index auf die erste Optionsmenge im Options-Array.\n</li><li><code>Index 2nd options</code>: 8 Bit (Bit offset 16–23), Index auf die zweite Optionsmenge im Options-Array.\n</li><li><code># of opt 1</code>: 4 Bit (Bit offset 24–27), Anzahl der Optionen der ersten Gruppe.\n</li><li><code># of opt 2</code>: 4 Bit (Bit offset 28–31), Anzahl der Optionen der zweiten Gruppe.\n</li><li><code>Service ID</code>: 16 Bit (Bit offset 0–15 des zweiten 32-Bit-Worts), eindeutige Dienstkennung.\n</li><li><code>Instance ID</code>: 16 Bit (Bit offset 16–31 des zweiten 32-Bit-Worts), Kennung der Dienstinstanz.\n</li><li><code>Major Version</code>: 8 Bit (Bit offset 0–7 des dritten 32-Bit-Worts), Hauptversionsnummer des angebotenen oder angeforderten Dienstes.\n</li><li><code>TTL</code> (Time to Live): 24 Bit (Bit offset 8–31 des dritten 32-Bit-Worts), Gültigkeitsdauer des Eintrags in Sekunden.\n</li><li><code>Minor Version</code>: 32 Bit (Bit offset 0–31 des vierten 32-Bit-Worts), Unterversionsnummer des Dienstes.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Datenformat ohne dynamischen Sequenzablauf. Bei der Serialisierung bzw. Deserialisierung eines SOME/IP-SD-Pakets werden die Felder in Big-Endian-Reihenfolge übertragen bzw. interpretiert. Der Sender füllt Dienstidentifikatoren, Versionsstände sowie Lebensdauer und referenziert über die Indizes und Zähler die zugehörigen Einträge im nachfolgenden Options-Array. Der Empfänger wertet diese Felder zur Dienstauflösung, Versionierungsprüfung und Verwaltung der dynamischen Service-Bindings aus.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Layout ist normativ für alle Type-1-Diensteinträge in SOME/IP Service Discovery. Feldgrenzen, Wortbreiten und Bit-Offsets müssen bitgenau eingehalten werden. Besondere Beachtung gilt der asymmetrischen Aufteilung des dritten Datenworts (8 Bit Major Version gefolgt von 24 Bit TTL) sowie der 4-Bit-Quantisierung der Optionszähler (<code># of opt 1</code>, <code># of opt 2</code>), die jeweils maximal 15 Optionen pro Referenzierungsblock zulässt.</p>"}, {"id": "FIG-96f3edee92a77794", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Protokoll- und Paketformat-Diagramm (Bit-/Byte-Layout eines Netzwerkprotokolls). Das Diagramm spezifiziert das exakte 16-Byte (128-Bit) umfassende Speicher- und Serialisierungsformat von „Type 1 Entries“ (Diensteinträge bzw. Entries for Services) innerhalb des SOME/IP Service Discovery Protokolls (SOME/IP-SD) auf Protokoll- bzw. Netzwerkebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Format ist als 32-Bit breites Raster strukturiert und gliedert sich in folgende Felder:</p>\n<ul class=\"fig-list\"><li><code>Type</code>: 8 Bit (Bit offset 0–7), Kennzeichnung des Eintragstyps.\n</li><li><code>Index 1st options</code>: 8 Bit (Bit offset 8–15), Index auf die erste Optionsmenge im Options-Array.\n</li><li><code>Index 2nd options</code>: 8 Bit (Bit offset 16–23), Index auf die zweite Optionsmenge im Options-Array.\n</li><li><code># of opt 1</code>: 4 Bit (Bit offset 24–27), Anzahl der Optionen der ersten Gruppe.\n</li><li><code># of opt 2</code>: 4 Bit (Bit offset 28–31), Anzahl der Optionen der zweiten Gruppe.\n</li><li><code>Service ID</code>: 16 Bit (Bit offset 0–15 des zweiten 32-Bit-Worts), eindeutige Dienstkennung.\n</li><li><code>Instance ID</code>: 16 Bit (Bit offset 16–31 des zweiten 32-Bit-Worts), Kennung der Dienstinstanz.\n</li><li><code>Major Version</code>: 8 Bit (Bit offset 0–7 des dritten 32-Bit-Worts), Hauptversionsnummer des angebotenen oder angeforderten Dienstes.\n</li><li><code>TTL</code> (Time to Live): 24 Bit (Bit offset 8–31 des dritten 32-Bit-Worts), Gültigkeitsdauer des Eintrags in Sekunden.\n</li><li><code>Minor Version</code>: 32 Bit (Bit offset 0–31 des vierten 32-Bit-Worts), Unterversionsnummer des Dienstes.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Datenformat ohne dynamischen Sequenzablauf. Bei der Serialisierung bzw. Deserialisierung eines SOME/IP-SD-Pakets werden die Felder in Big-Endian-Reihenfolge übertragen bzw. interpretiert. Der Sender füllt Dienstidentifikatoren, Versionsstände sowie Lebensdauer und referenziert über die Indizes und Zähler die zugehörigen Einträge im nachfolgenden Options-Array. Der Empfänger wertet diese Felder zur Dienstauflösung, Versionierungsprüfung und Verwaltung der dynamischen Service-Bindings aus.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Layout ist normativ für alle Type-1-Diensteinträge in SOME/IP Service Discovery. Feldgrenzen, Wortbreiten und Bit-Offsets müssen bitgenau eingehalten werden. Besondere Beachtung gilt der asymmetrischen Aufteilung des dritten Datenworts (8 Bit Major Version gefolgt von 24 Bit TTL) sowie der 4-Bit-Quantisierung der Optionszähler (<code># of opt 1</code>, <code># of opt 2</code>), die jeweils maximal 15 Optionen pro Referenzierungsblock zulässt.</p>"}], "trans": [{"from": "FIG-5ba226bbda222c4a", "to": "FIG-a2e1cb92ea5e27ca", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-a2e1cb92ea5e27ca", "to": "FIG-8eb569ef7fc86f0e", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-8eb569ef7fc86f0e", "to": "FIG-96f3edee92a77794", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
